import numpy as np
r=Robot();o=r.get_obs(video='none');seed=np.array(o.meta['proprio']['now'][:7]);d=np.array([0.,-.70710678,.70710678,0.]);
def mul(a,b):
 w,x,y,z=a;W,X,Y,Z=b
 return np.array([w*W-x*X-y*Y-z*Z,w*X+x*W+y*Z-z*Y,w*Y-x*Z+y*W+z*X,w*Z+x*Y-y*X+z*W])
for deg in [42,43,45,41]:
 q=mul([np.cos(np.deg2rad(deg)/2),0,0,np.sin(np.deg2rad(deg)/2)],d)
 print(deg,q)
 for name,xy,z in [('above',(.425,.207),.17),('grasp',(.425,.207),.015),('pot',(.467,-.017),.19)]:
  a=r.ik({'tcp':[xy[0],xy[1],z,*q]},seed=seed); print(name,a['ok'],a.get('error'))
PY

